package org.apache.commons.text.similarity;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class LongestCommonSubsequence_ESTest_test08 extends LongestCommonSubsequence_ESTest_scaffolding {

    /** The NUL U+0000'�') character, shared by both inputs below. */
    private static final char NUL = (char) 0;

    /**
     * The two inputs share exactly one character, so the longest common
     * subsequence has length 1.
     *
     * left  = {NUL, 'r'}
     * right = {NUL, NUL}  (a CharBuffer over a freshly allocated char[2],
     *                      which Java zero-initializes to NUL characters)
     *
     * The only character common to both sequences is the NUL character.
     */
    @Test(timeout = 4000)
    public void applyReturnsLengthOfSingleSharedCharacter() throws Throwable {
        LongestCommonSubsequence lcs = new LongestCommonSubsequence();

        CharSequence left = new String(new char[] { NUL, 'r' });
        // A char[2] is zero-initialized, so this CharBuffer holds two NUL chars.
        CharSequence right = CharBuffer.wrap(new char[2]);

        Integer lcsLength = lcs.apply(left, right);

        assertEquals(1, (int) lcsLength);
    }
}
